def ingest(doc, state, index):
    # re-embed only when text, parser, chunker or embedding model changes
    fp = sha256(f"{doc.text}|{PARSER_V}|{CHUNKER_V}|{EMBED_MODEL}".encode()).hexdigest()
    if state.get(doc.id) == fp:
        return                                  # unchanged: no embedding cost
    rows = [
        {"id": f"{doc.id}-{i}", "parent_id": doc.id, "content_hash": fp,
         "content": c, "vector": embed(c)}
        for i, c in enumerate(split(doc.text))
    ]
    index.merge_or_upload(rows)                 # replay-safe upsert by key
    index.delete_where(parent_id=doc.id, id_not_in=[r["id"] for r in rows])  # stale tail chunks
    state[doc.id] = fp                          # written last, so a crash replays the document
